    explanation: "AWS's data privacy principles state that customers maintain ownership and control of their content: they choose where it is stored, how it is secured, and who can access it. AWS does not access or use customer content for any purpose without the customer's agreement, except as legally required, and content stays in the Region the customer selects unless the customer moves it. Encryption with customer-controlled keys further limits what anyone, including AWS, can see.",
